  /** 지도에서 잘라 쓸 위도 범위. */
  const LAT_TOP = 84;
  const LAT_BOTTOM = -58;

  let cache = null;

  function decodeRing(ring) {
    const nums = ring.split(',');
    const out = new Float64Array(nums.length);
    let x = 0;
    let y = 0;
    for (let i = 0; i < nums.length; i += 2) {
      x += +nums[i];
      y += +nums[i + 1];
      out[i] = x / 100;
      out[i + 1] = y / 100;
    }
    return out;
  }

  /** 육지 목록 — 각 항목은 링 배열이고 첫 링이 겉테두리다. */
  function landmasses() {
    if (!cache) cache = DATA.split(';').map((poly) => poly.split('|').map(decodeRing));
    return cache;
  }

  root.AirlinerWorld = { LAT_TOP, LAT_BOTTOM, landmasses };
